    }

pub fn fromMimeType(mime_type: bun.http.MimeType) Loader {
            if (strings.hasPrefixComptime((if (@typeInfo(@TypeOf(mime_type)) == .@"enum") @intFromEnum(mime_type) else mime_type.value), "application/javascript-jsx")) {
                return .jsx;
            } else {
                if (strings.hasPrefixComptime((if (@typeInfo(@TypeOf(mime_type)) == .@"enum") @intFromEnum(mime_type) else mime_type.value), "application/typescript-jsx")) {
                    return .tsx;
                } else {
                    if (strings.hasPrefixComptime((if (@typeInfo(@TypeOf(mime_type)) == .@"enum") @intFromEnum(mime_type) else mime_type.value), "application/javascript")) {
                        return .js;
                    } else {
                        if (strings.hasPrefixComptime((if (@typeInfo(@TypeOf(mime_type)) == .@"enum") @intFromEnum(mime_type) else mime_type.value), "application/typescript")) {
                            return .ts;
                        } else {
                            if (strings.hasPrefixComptime((if (@typeInfo(@TypeOf(mime_type)) == .@"enum") @intFromEnum(mime_type) else mime_type.value), "application/json5")) {
                                return .json5;
                            } else {
                                if (strings.hasPrefixComptime((if (@typeInfo(@TypeOf(mime_type)) == .@"enum") @intFromEnum(mime_type) else mime_type.value), "application/jsonc")) {
                                    return .jsonc;
                                } else {
                                    if (strings.hasPrefixComptime((if (@typeInfo(@TypeOf(mime_type)) == .@"enum") @intFromEnum(mime_type) else mime_type.value), "application/json")) {
                                        return .json;
                                    } else {
                                        if ((mime_type.category == .text)) {
                                            return .text;
                                        } else {
                                            return .tsx;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
    }
    
